<?php get_header(); if ( staffswap_builder_location( 'archive' ) ) { get_footer(); return; } ?><div class="content-form"><h1><?php the_archive_title(); ?></h1><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><article class="article-card" style="margin-top:16px"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile; else : ?><div class="panel"><p><?php echo esc_html__( 'No content found.', 'staffswap' ); ?></p></div><?php endif; ?></div><?php get_footer(); ?>
